examples.template:
MonarchOnboardingChecklist(
    {{title}},
    steps: steps,
    description: {{description}},
    onDismiss: {},
    action: { step in
        if step.id == {{steps.1.id}} {
            Button({{steps.1.action.label}}) {}
                .buttonStyle(.monarch({{steps.1.action.variant|case}}, size: .sm))
        } else if step.id == {{steps.2.id}} {
            Button({{steps.2.action.label}}) {}
                .buttonStyle(.monarch({{steps.2.action.variant|case}}, size: .sm))
        } else if step.id == {{steps.3.id}} {
            Button({{steps.3.action.label}}) {}
                .buttonStyle(.monarch({{steps.3.action.variant|case}}, size: .sm))
        }
    }
)

examples.setupTemplate:
@State private var steps = [
    MonarchOnboardingStep(id: {{steps.0.id}}, title: {{steps.0.title}}, isDone: {{steps.0.done}}),
    MonarchOnboardingStep(id: {{steps.1.id}}, title: {{steps.1.title}}, description: {{steps.1.description}}),
    MonarchOnboardingStep(id: {{steps.2.id}}, title: {{steps.2.title}}, description: {{steps.2.description}}),
    MonarchOnboardingStep(id: {{steps.3.id}}, title: {{steps.3.title}}),
]

examples.setup:
@State private var steps = [
    MonarchOnboardingStep(id: "profile", title: "Complete your profile", isDone: true),
    MonarchOnboardingStep(id: "invite", title: "Invite your team", description: "Work is easier to share with the people you work with."),
    MonarchOnboardingStep(id: "project", title: "Create your first project", description: "Start from a template or a blank project."),
    MonarchOnboardingStep(id: "notifications", title: "Choose your notifications"),
]

examples.code:
MonarchOnboardingChecklist(
    "Get started",
    steps: steps,
    description: "A few steps to set up your workspace.",
    onDismiss: {},
    action: { step in
        if step.id == "invite" {
            Button("Invite people") {}
                .buttonStyle(.monarch(.secondary, size: .sm))
        } else if step.id == "project" {
            Button("New project") {}
                .buttonStyle(.monarch(.secondary, size: .sm))
        } else if step.id == "notifications" {
            Button("Open settings") {}
                .buttonStyle(.monarch(.ghost, size: .sm))
        }
    }
)
